const CSS="\n:root{color-scheme:dark;--bg:#090e1b;--side:#0e1528;--panel:#121c32;--soft:#19253d;--edge:#28364c;--text:#f3f7ff;--muted:#93a4c1;--aqua:#3ce7c4;--blue:#789cff;--orange:#ffc47c}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse 900px 560px at 80% -8%,#17334b 0%,transparent 60%),var(--bg);font-family:Tahoma,\"Segoe UI\",Arial,sans-serif;color:var(--text);min-height:100vh}button,input{font:inherit}button{cursor:pointer}a{text-decoration:none;color:inherit}.boot{padding:100px;text-align:center;color:var(--muted)}.login-wrap{min-height:100vh;display:grid;place-items:center;padding:24px}.login-card{max-width:430px;width:100%;background:#121e33;border:1px solid var(--edge);border-radius:24px;padding:36px;box-shadow:0 25px 90px #0008}.symbol{display:grid;place-items:center;width:55px;height:55px;border-radius:17px;background:linear-gradient(145deg,#2ae2ba,#4e8dff);color:#061625;font-weight:bold;font-size:28px}.login-card h1{font-size:23px;margin:21px 0 6px}.muted{color:var(--muted)}.small{font-size:12px}.login-card label{display:block;margin:22px 0 7px;font-size:13px}.login-card input,.field{width:100%;padding:13px;border:1px solid #35425a;border-radius:11px;background:#0d1526;color:var(--text);outline:none;direction:ltr;text-align:left}.login-card input:focus,.field:focus{border-color:var(--aqua)}.btn{background:var(--aqua);color:#04231d;font-weight:700;border:0;border-radius:11px;padding:12px 18px}.btn.secondary{background:#22334d;color:#dce9ff}.btn.warn{background:#4a2f3a;color:#fff}.btn:disabled{opacity:.45;cursor:wait}.error{color:#ff9a9a;font-size:13px;min-height:22px;margin:10px 0}.shell{display:flex;min-height:100vh}.sidebar{width:252px;flex:none;background:#0c1425;border-left:1px solid var(--edge);padding:28px 17px;position:sticky;top:0;height:100vh;overflow:auto}.brand{display:flex;align-items:center;gap:12px;margin:0 4px 36px;font-size:18px;font-weight:800}.brand small{font-size:11px;font-weight:400;color:var(--muted);display:block;margin-top:5px}.nav-caption{font-size:11px;color:#72839f;margin:23px 12px 10px}.nav{display:block;padding:12px 13px;color:#b4c2d7;font-size:13px;border-radius:10px;margin:3px 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.nav:hover{background:#172640}.nav.active{background:#173840;color:var(--aqua);font-weight:bold}.bottom-nav{margin-top:44px}.main{flex:1;min-width:0;padding:34px max(22px,4vw) 90px;max-width:1600px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:25px}.eyebrow{color:var(--aqua);font-size:12px;letter-spacing:.6px}.top h1{font-size:27px;margin:9px 0 8px}.top p{color:var(--muted);margin:0;font-size:13px}.pill{display:inline-block;padding:7px 12px;border:1px solid #335067;background:#173046;border-radius:999px;font-size:12px;color:#a5e7e1}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.card,.panel{background:linear-gradient(155deg,#142139,#101b30);border:1px solid #25354f;border-radius:17px;padding:21px}.card .label{font-size:13px;color:#98aacc}.card .big{font-size:29px;font-weight:800;margin:16px 0 9px;line-height:1.3}.big,.num{font-variant-numeric:tabular-nums;direction:ltr;unicode-bidi:isolate}.card .foot{font-size:11px;color:#84bfb1}.section{margin-top:21px}.twocol{display:grid;grid-template-columns:1.05fr .95fr;gap:18px}.panel h3{margin:0 0 19px;font-size:16px}.chart-list{display:grid;gap:17px}.bar-head{display:flex;justify-content:space-between;gap:15px;font-size:12px;margin-bottom:7px}.bar-head span:last-child{direction:ltr;color:#d9e9ff}.track{height:9px;background:#25334b;border-radius:8px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,#28c9b6,#6b92f7);border-radius:8px}.hint{font-size:11px;color:var(--muted);line-height:2}.tablebox{overflow-x:auto}.data-table{width:100%;border-collapse:collapse;font-size:12px;white-space:nowrap}.data-table th{text-align:right;color:var(--muted);font-weight:400;padding:13px 12px;border-bottom:1px solid var(--edge)}.data-table td{padding:14px 12px;border-bottom:1px solid #243149}.data-table tr:last-child td{border-bottom:0}.data-table td:nth-child(n+2),.data-table th:nth-child(n+2){text-align:left;direction:ltr}.path{max-width:400px;overflow:hidden;text-overflow:ellipsis;direction:ltr;text-align:right!important;unicode-bidi:plaintext}.tag{border:1px solid #39516a;border-radius:20px;padding:4px 8px;color:#b9d6f0;font-size:11px}.empty{padding:55px 20px;text-align:center;color:var(--muted);line-height:2}.site-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.site-card{display:block;background:#142139;border:1px solid #2c3e56;padding:23px;border-radius:16px;transition:transform .15s, border-color .15s}.site-card:hover{border-color:var(--aqua);transform:translateY(-2px)}.site-card h3{margin:6px 0 12px}.site-card .domain{direction:ltr;text-align:right;font-size:12px;color:#8aaad1}.site-card .state{font-size:11px;color:#8ee9d4;margin-top:20px}.toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.message{background:#173247;border:1px solid #34576b;padding:15px 20px;border-radius:11px;color:#c6eeee;font-size:13px;margin-top:20px;white-space:pre-wrap;overflow-wrap:anywhere}.notice{border-right:3px solid #e7bb66;padding:12px 15px;background:#30283a;color:#ead8b1;font-size:12px;border-radius:6px;line-height:2}.link{color:#8decdb}.fieldlabel{font-size:12px;color:var(--muted);display:block;margin:10px 0 7px}.modal-bg{position:fixed;inset:0;background:#000b;display:grid;place-items:center;z-index:99;padding:14px}.dialog{background:#142138;border:1px solid #40506b;width:min(460px,100%);border-radius:19px;padding:28px}.dialog h3{margin-top:0}.dialog .toolbar{margin-top:22px}.code{font-family:Consolas,monospace;direction:ltr;display:block;text-align:left;overflow-wrap:anywhere;padding:14px;background:#081323;border-radius:8px}@media(max-width:1050px){.cards{grid-template-columns:repeat(2,1fr)}.twocol{grid-template-columns:1fr}.site-list{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.sidebar{width:74px;padding:20px 9px}.brand span,.sidebar .nav-caption,.sidebar .nav-text,.sidebar .bottom-nav{display:none}.brand{margin:0 0 25px}.brand .symbol{width:44px;height:44px}.nav{font-size:18px;padding:13px 4px;text-align:center}.main{padding:24px 13px}.top h1{font-size:21px}.cards{gap:9px}.card,.panel{padding:15px}.card .big{font-size:23px}.site-list{grid-template-columns:1fr}.top .pill{font-size:10px}}\n\n/* Site-focused reporting navigation and analytical UX */\n.site-identity{margin:6px 8px 22px;background:#162a40;border:1px solid #29445b;padding:12px;border-radius:12px;overflow:hidden}\n.site-identity b{display:block;font-size:14px;margin-bottom:6px}.site-identity small{font-size:11px;color:#98afc9;direction:ltr;unicode-bidi:plaintext;display:block;overflow:hidden;text-overflow:ellipsis}\n.nav-icon{display:inline-block;min-width:24px;font-size:17px;text-align:center;margin-left:7px}\n.site-topnav{display:none;gap:7px;overflow-x:auto;white-space:nowrap;padding:6px 0 10px}\n.topnav-link{padding:9px 13px;background:#16243a;border:1px solid #2b3c54;color:#b3c9dd;border-radius:10px;font-size:12px}\n.topnav-link.selected{background:#1b484a;color:#7df4d5;border-color:#2b7a73}\n.section-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:15px}.section-head h3{margin:0}\n.subtle-note{font-size:12px;color:#9eb2cd}.pill-warn{background:#392d32!important;border-color:#77524e!important;color:#ffdfbd!important}\n.explain{color:#9eb0ca;font-size:12px;line-height:2;margin:20px 0}\n.insights{display:grid;gap:13px;font-size:13px;line-height:1.9;color:#d6e7f7}\n.text-link{color:#73e4d6;text-decoration:none;font-size:12px;white-space:nowrap}.text-link:hover{text-decoration:underline}\n.searchbox{padding:11px 13px;border-radius:10px;background:#0d1729;color:#e8f2ff;border:1px solid #3a4a63;min-width:175px;max-width:100%;font-size:12px}\n.toolbar .searchbox{flex:1}.results-meta{padding:15px 0;color:#9fbed0;font-size:12px}\n.pager{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:19px;color:#a4bdd4;font-size:12px}\n.btn-sm{padding:8px 13px;font-size:12px}.chMetric.active{background:#257d7a;color:white}\n.click-row{cursor:pointer}.click-row:hover{background:#20364b}.detail{background:#102941;border:1px solid #357178;padding:19px;border-radius:12px;margin:20px 0}.detail-cards{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:15px 0}.detail-cards>div{background:#193d50;padding:14px;border-radius:10px}.detail-cards small{display:block;color:#a8cbd2;margin-bottom:9px}.detail-cards b{font-size:19px}\n.funnel{display:grid;gap:13px}.funnel-step{display:flex;align-items:center;gap:14px;background:#1b2a43;padding:15px;border-radius:12px}.step-no{background:#225470;color:#e5ffff;min-width:32px;height:32px;display:grid;place-items:center;border-radius:50%}.funnel-step b{display:block;font-size:14px}.funnel-step small{display:block;color:#89a9c6;font-size:11px;margin-top:5px}.step-status{margin-right:auto;font-size:12px;color:#b3dcd0}\n@media(max-width:850px){.site-topnav{display:flex}.detail-cards{grid-template-columns:repeat(2,1fr)}.site-identity{padding:8px 4px;margin:4px 0 18px}.site-identity b,.site-identity small{display:none}}\n@media(max-width:500px){.main{padding:17px 12px 70px}.top h1{font-size:20px}.toolbar .searchbox{min-width:100%;width:100%}.section-head{align-items:flex-start}.detail-cards b{font-size:16px}.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.nav-icon{margin:0}}\n\n.period-picker{display:flex;align-items:center;gap:9px;color:#9db9cb;font-size:12px}.period-picker .searchbox{min-width:250px;max-width:100%}@media(max-width:600px){.period-picker{width:100%;justify-content:space-between}.period-picker .searchbox{min-width:180px;width:100%}}\n\n.glossary summary{cursor:pointer;font-weight:700;color:#b4e9e2;padding:5px 0}.glossary p{font-size:12px;color:#a9c3d9;line-height:2;margin:10px 0}\n\n.daily-bars{display:flex;align-items:flex-end;gap:3px;overflow-x:auto;height:150px;border-bottom:1px solid #30516a}.daily-col{min-width:7px;flex:1;display:flex;height:140px;align-items:flex-end}.daily-bar{width:100%;border-radius:4px 4px 0 0;background:linear-gradient(180deg,#48e9b9,#607cf7)}.daily-col:hover .daily-bar{background:#76f4cf}\n";
const CLIENT="\nconst $=s=>document.querySelector(s), fmt=n=>n===null||n===undefined?'—':new Intl.NumberFormat('fa-IR').format(n),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst state={me:null,sites:[],dashboard:null};\nasync function api(path,options={}){const r=await fetch(path,{credentials:'same-origin',headers:{'content-type':'application/json'},...options});let j=await r.json();if(!r.ok)throw Error(j.error||'خطا در ارتباط با سرور');return j;}\nfunction nav(path){const current=location.pathname.match(/^\\/s\\/([a-z0-9-]+)/),dest=path.match(/^\\/s\\/([a-z0-9-]+)/);if(current&&dest&&current[1]===dest[1]&&location.search&&!path.includes(\"?\"))path+=location.search;history.pushState({},'',path);render();}\nfunction pageTitle(t,sub){return '<div class=\"top\"><div><div class=\"eyebrow\">CLIENT ANALYTICS HUB / گزارش مشتریان</div><h1>'+esc(t)+'</h1><p>'+esc(sub)+'</p></div><span class=\"pill\">● پلتفرم اختصاصی</span></div>'}\n\nconst siteSections=[[\"overview\",\"◈\",\"نمای کلی\"],[\"channels\",\"◉\",\"کانال‌های جذب\"],[\"landing\",\"▤\",\"صفحات ورودی\"],[\"journey\",\"⇢\",\"قیف و مسیر خرید\"],[\"quality\",\"◎\",\"کیفیت داده‌ها\"]];\nconst panelState={query:\"\",pageType:\"all\",sort:\"orders\",page:0,channel:null,metric:\"orders\"};\nfunction sitePath(slug,tab=\"overview\"){return \"/s/\"+encodeURIComponent(slug)+(tab===\"overview\"?\"\":\"/\"+tab);}\nfunction layout(content,selected,tab=\"overview\"){\n let links,caption;\n if(selected){\n  const s=state.dashboard?.site||state.sites.find(x=>x.slug===selected)||{name:selected,domain:\"\"};\n  caption='<span class=\"nav-caption\">پنل اختصاصی</span><div class=\"site-identity\"><b>'+esc(s.name)+'</b><small>'+esc(s.domain||\"\")+'</small></div><div class=\"nav-caption\">تحلیل‌های سایت</div>';\n  links=siteSections.map(([key,icon,name])=>'<a class=\"nav '+(tab===key?'active':'')+'\" href=\"'+sitePath(selected,key)+'\" data-link=\"'+sitePath(selected,key)+'\" title=\"'+esc(name)+'\"><span class=\"nav-icon\">'+icon+'</span><span class=\"nav-text\">'+esc(name)+'</span></a>').join('');\n  if(state.me.role===\"admin\") links+='<div class=\"nav-caption\">مدیریت</div><a class=\"nav\" href=\"/admin\" data-link=\"/admin\" title=\"بازگشت به فهرست سایت‌ها\"><span class=\"nav-icon\">↩</span><span class=\"nav-text\">بازگشت به همه سایت‌ها</span></a>';\n }else{\n  caption='<div class=\"nav-caption\">مدیریت مرکزی</div>';\n  links='<a class=\"nav active\" href=\"/admin\" data-link=\"/admin\" title=\"همه سایت‌ها\"><span class=\"nav-icon\">▦</span><span class=\"nav-text\">همه سایت‌ها</span></a><div class=\"nav-caption\">پنل‌های مستقل</div>'+state.sites.filter(x=>!x.archived_at).map(x=>'<a class=\"nav\" href=\"'+sitePath(x.slug)+'\" data-link=\"'+sitePath(x.slug)+'\" title=\"'+esc(x.name)+'\"><span class=\"nav-icon\">◉</span><span class=\"nav-text\">'+esc(x.name)+'</span></a>').join('');\n }\n return '<div class=\"shell\"><aside class=\"sidebar\"><div class=\"brand\"><div class=\"symbol\">A</div><span>Analytics Hub<small>گزارش‌های دیجیتال مارکتینگ</small></span></div>'+caption+links+'<div class=\"bottom-nav\"><a class=\"nav\" href=\"#\" id=\"logout\" title=\"خروج\"><span class=\"nav-icon\">⇥</span><span class=\"nav-text\">خروج از حساب</span></a></div></aside><main class=\"main\">'+content+'</main></div>';\n}\nfunction login(){const ref=location.pathname.match(/^\\/s\\/([a-z0-9-]+)/);$('#app').innerHTML='<div class=\"login-wrap\"><form class=\"login-card\" id=\"loginform\"><div class=\"symbol\">A</div><h1>ورود به داشبورد تحلیلی</h1><p class=\"muted small\">دسترسی هر کارفرما فقط به داده‌های سایت خودش محدود شده است.</p><label>نام کاربری</label><input required name=\"username\" autocomplete=\"username\" placeholder=\"username\" autofocus><label>رمز عبور</label><input required type=\"password\" name=\"password\" autocomplete=\"current-password\" placeholder=\"Password\"><div class=\"error\" id=\"err\"></div><button class=\"btn\" type=\"submit\" style=\"width:100%\">ورود امن به پنل</button></form></div>';$('#loginform').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));await api('/api/login',{method:'POST',body:JSON.stringify(d)});await init();}catch(err){$('#err').textContent=err.message}finally{b.disabled=false}};}\n\nfunction siteManager(){\n const actives=state.sites.filter(s=>!s.archived_at),archived=state.sites.filter(s=>s.archived_at);\n const cards=actives.map(s=>'<div class=\"site-card\"><a href=\"/s/'+esc(s.slug)+'\" data-link=\"/s/'+esc(s.slug)+'\"><div class=\"tag\">'+(s.state==='live'?'همگام‌سازی فعال':s.state==='snapshot'?'داده تاریخی':'بدون اطلاعات')+'</div><h3>'+esc(s.name)+'</h3><div class=\"domain\">'+esc(s.domain)+'</div><div class=\"state\">مشاهده داشبورد ←</div></a><div class=\"toolbar section\"><button class=\"btn secondary btn-sm sync-site\" data-slug=\"'+esc(s.slug)+'\">↻ به‌روزرسانی</button><button class=\"btn secondary btn-sm connect-site\" data-slug=\"'+esc(s.slug)+'\">اتصال ووکامرس</button><button class=\"btn secondary btn-sm connect-ga4\" data-slug=\"'+esc(s.slug)+'\">اتصال GA4</button><button class=\"btn secondary btn-sm sync-ga4\" data-slug=\"'+esc(s.slug)+'\">↻ دریافت GA4</button><button class=\"btn warn btn-sm archive-site\" data-slug=\"'+esc(s.slug)+'\">حذف</button></div><div class=\"small muted section\">آخرین اتصال: '+esc((s.last_status==='ok'?'موفق':s.last_status==='error'?'خطای دریافت':s.last_status==='running'?'در حال دریافت':'بدون اتصال')+' · '+(s.last_success_at||'هنوز به‌روز نشده')+(s.last_error?' · '+s.last_error:''))+'</div></div>').join('');\n const archiveCards=archived.map(s=>'<div class=\"site-card\"><div class=\"tag\">بایگانی شده</div><h3>'+esc(s.name)+'</h3><div class=\"domain\">'+esc(s.domain)+'</div><div class=\"toolbar section\"><button class=\"btn secondary restore-site\" data-slug=\"'+esc(s.slug)+'\">بازگردانی پنل</button></div></div>').join('');\n const userRows=(state.users||[]).map(u=>'<tr><td>'+esc(u.username)+'</td><td>'+esc(u.site_slug)+'</td><td>'+ (u.active?'فعال':'غیرفعال')+'</td><td><button class=\"btn secondary btn-sm user-toggle\" data-username=\"'+esc(u.username)+'\" data-active=\"'+(u.active?'0':'1')+'\">'+(u.active?'لغو دسترسی':'فعال‌سازی')+'</button> <button class=\"btn secondary btn-sm user-reset\" data-username=\"'+esc(u.username)+'\">رمز جدید</button></td></tr>').join('');\n const html=pageTitle('مدیریت مرکزی سایت‌ها','افزودن و بایگانی سایت، دسترسی اختصاصی مدیر هر سایت و همگام‌سازی اطلاعات')+'<div class=\"toolbar\"><button id=\"addsite\" class=\"btn\">+ افزودن سایت</button><button id=\"addviewer\" class=\"btn secondary\">+ افزودن مدیر سایت</button></div><div class=\"section site-list\">'+cards+'</div>'+(archived.length?'<div class=\"section panel\"><h3>سایت‌های بایگانی‌شده</h3><div class=\"site-list\">'+archiveCards+'</div></div>':'')+'<div class=\"section panel\"><h3>مدیریت حساب مدیران سایت</h3>'+table(['نام کاربری','سایت مجاز','وضعیت','عملیات'],userRows? [userRows]:[])+'<p class=\"hint\">هر حساب فقط اطلاعات سایت اختصاص داده شده به خودش را مشاهده می‌کند. لغو دسترسی، نشست‌های قبلی را هم بی‌اعتبار می‌کند.</p></div><p class=\"notice section\">اطلاعات تازه فقط برای سایت‌هایی دریافت می‌شود که کلیدهای خواندنی WooCommerce آن‌ها ثبت شده باشد. وضعیت آخرین همگام‌سازی در هر پنل نمایش داده می‌شود.</p>';\n $('#app').innerHTML=layout(html,null);\n $('#addsite').onclick=()=>dialog('افزودن سایت',[['slug','شناسه انگلیسی'],['name','نام فارسی'],['domain','دامنه، بدون https://']],'/api/admin/sites');\n $('#addviewer').onclick=()=>dialog('ساخت حساب مدیر اختصاصی',[['username','نام کاربری انگلیسی'],['site_slug','شناسه سایت (مثلاً moorashin)']],'/api/admin/users');\n document.querySelectorAll('.archive-site').forEach(el=>el.onclick=async()=>{const slug=el.dataset.slug;const typed=prompt('برای بایگانی '+slug+' شناسه سایت را دقیقاً وارد کنید. حساب‌های آن سایت قطع می‌شوند و اطلاعات محفوظ می‌مانند.');if(typed!==slug)return;try{await api('/api/admin/sites/archive',{method:'POST',body:JSON.stringify({site_slug:slug,confirm_slug:typed})});await loadSites();siteManager();}catch(e){alert(e.message)}});\n document.querySelectorAll('.restore-site').forEach(el=>el.onclick=async()=>{if(!confirm('سایت '+el.dataset.slug+' برگردانده شود؟ حساب‌های قبلی همچنان غیرفعال می‌مانند.'))return;try{await api('/api/admin/sites/restore',{method:'POST',body:JSON.stringify({site_slug:el.dataset.slug})});await loadSites();siteManager();}catch(e){alert(e.message)}});\n document.querySelectorAll('.connect-site').forEach(el=>el.onclick=()=>connectWooDialog(el.dataset.slug));\n document.querySelectorAll('.connect-ga4').forEach(el=>el.onclick=()=>ga4ConnectDialog(el.dataset.slug));\n document.querySelectorAll('.sync-ga4').forEach(el=>el.onclick=async()=>{el.disabled=true;el.textContent='در حال دریافت GA4';try{const r=await api('/api/admin/ga4/sync',{method:'POST',body:JSON.stringify({site_slug:el.dataset.slug})});alert('دریافت موفق: '+fmt(r.channels)+' ردیف منابع، '+fmt(r.landingPages)+' صفحه GA4');await loadSites();siteManager();}catch(err){alert(err.message);el.disabled=false;el.textContent='↻ دریافت GA4'}});\n document.querySelectorAll('.sync-site').forEach(el=>el.onclick=async()=>{el.disabled=true;el.textContent='در حال دریافت...';try{const r=await api('/api/admin/woocommerce/sync',{method:'POST',body:JSON.stringify({site_slug:el.dataset.slug})});alert('ثبت شد: '+fmt(r.paid_orders)+' سفارش پرداخت‌شده');await loadSites();siteManager();}catch(e){alert(e.message);el.disabled=false;el.textContent='↻ به‌روزرسانی';}});\n document.querySelectorAll('.user-toggle').forEach(el=>el.onclick=async()=>{try{await api('/api/admin/users/status',{method:'POST',body:JSON.stringify({username:el.dataset.username,active:el.dataset.active==='1'})});await loadSites();siteManager();}catch(e){alert(e.message)}});\n document.querySelectorAll('.user-reset').forEach(el=>el.onclick=async()=>{if(!confirm('برای '+el.dataset.username+' رمز جدید تولید شود؟'))return;try{const r=await api('/api/admin/users/reset',{method:'POST',body:JSON.stringify({username:el.dataset.username})});passwordNotice(r);}catch(e){alert(e.message)}});\n}\nfunction passwordNotice(r){const overlay=document.createElement('div');overlay.className='modal-bg';overlay.innerHTML='<div class=\"dialog\"><h3>اطلاعات ورود جدید</h3><p class=\"notice\">این رمز فقط همین بار نمایش داده می‌شود؛ آن را امن به مدیر همان سایت ارسال کن.</p><p>نام کاربری</p><code class=\"code\">'+esc(r.username)+'</code><p>رمز عبور</p><code class=\"code\">'+esc(r.password)+'</code><button type=\"button\" class=\"btn\" id=\"secretclose\">بستن</button></div>';document.body.append(overlay);overlay.querySelector('#secretclose').onclick=()=>overlay.remove();}\n\nfunction ga4ConnectDialog(slug){\n const overlay=document.createElement(\"div\");overlay.className=\"modal-bg\";\n overlay.innerHTML='<form class=\"dialog\" id=\"ga4form\"><h3>اتصال Google Analytics 4 به '+esc(slug)+'</h3><p class=\"hint\">شناسه عددی Property را وارد کن. این Property باید با اکانت GA4 متصل به Cloudflare قابل خواندن باشد.</p><label class=\"fieldlabel\">GA4 Property ID</label><input class=\"field\" name=\"property_id\" required pattern=\"[0-9]{6,14}\" inputmode=\"numeric\" placeholder=\"559100143\"><div class=\"error\" id=\"ga4error\"></div><div class=\"toolbar\"><button class=\"btn\" type=\"submit\">ثبت اتصال GA4</button><button class=\"btn secondary\" id=\"ga4cancel\" type=\"button\">انصراف</button></div></form>';\n document.body.append(overlay);overlay.querySelector('#ga4cancel').onclick=()=>overlay.remove();overlay.querySelector('#ga4form').onsubmit=async e=>{e.preventDefault();try{const values=Object.fromEntries(new FormData(e.target));await api('/api/admin/ga4/connect',{method:'POST',body:JSON.stringify({...values,site_slug:slug})});overlay.remove();alert(\"Property ثبت شد؛ دکمه دریافت GA4 را بزن.\")}catch(err){overlay.querySelector('#ga4error').textContent=err.message}};\n}\n\nfunction connectWooDialog(slug){const overlay=document.createElement('div');overlay.className='modal-bg';overlay.innerHTML='<form class=\"dialog\" id=\"wcform\"><h3>اتصال فروشگاه '+esc(slug)+'</h3><p class=\"hint\">یک کلید WooCommerce REST API با مجوز Read ایجاد کن. کلیدها رمزگذاری می‌شوند و در پنل نمایش داده نخواهند شد.</p><label class=\"fieldlabel\">Consumer Key</label><input required class=\"field\" name=\"consumer_key\" autocomplete=\"off\"><label class=\"fieldlabel\">Consumer Secret</label><input required class=\"field\" name=\"consumer_secret\" type=\"password\" autocomplete=\"off\"><div id=\"wcerror\" class=\"error\"></div><div class=\"toolbar\"><button type=\"submit\" class=\"btn\">ذخیره اتصال امن</button><button type=\"button\" class=\"btn secondary\" id=\"wccancel\">انصراف</button></div></form>';document.body.append(overlay);overlay.querySelector('#wccancel').onclick=()=>overlay.remove();overlay.querySelector('#wcform').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.site_slug=slug;try{await api('/api/admin/woocommerce/connect',{method:'POST',body:JSON.stringify(data)});overlay.remove();await loadSites();siteManager();alert('اتصال ثبت شد. اکنون دکمه به‌روزرسانی را بزن.');}catch(err){overlay.querySelector('#wcerror').textContent=err.message}};}\nfunction dialog(title,fields,url){const html='<div class=\"modal-bg\"><form class=\"dialog\" id=\"popup\"><h3>'+esc(title)+'</h3>'+fields.map(([key,label])=>'<label class=\"fieldlabel\">'+esc(label)+'</label><input required class=\"field\" name=\"'+esc(key)+'\">').join('')+'<div id=\"dialog-msg\" class=\"error\"></div><div class=\"toolbar\"><button type=\"submit\" class=\"btn\">ثبت</button><button class=\"btn secondary\" type=\"button\" id=\"close-modal\">بستن</button></div></form></div>';document.body.insertAdjacentHTML('beforeend',html);$('#close-modal').onclick=()=>$('.modal-bg').remove();$('#popup').onsubmit=async e=>{e.preventDefault();try{const result=await api(url,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});if(result.password){$('.modal-bg').remove();passwordNotice(result);await loadSites();siteManager();}else{$('.modal-bg').remove();await loadSites();siteManager();}}catch(err){$('#dialog-msg').textContent=err.message}};}\nfunction bar(title,rows,field){let max=Math.max(1,...rows.map(v=>Number(v[field])||0));return '<div class=\"panel\"><h3>'+esc(title)+'</h3><div class=\"chart-list\">'+rows.map(r=>'<div><div class=\"bar-head\"><span>'+esc(r.channel||r.page_type)+'</span><span>'+fmt(r[field])+(field==='orders'?' سفارش':' تومان')+'</span></div><div class=\"track\"><div class=\"fill\" style=\"width:'+((Number(r[field])||0)/max*100).toFixed(1)+'%\"></div></div></div>').join('')+'</div></div>';}\nfunction table(headers,rows){return '<div class=\"tablebox\"><table class=\"data-table\"><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>';}\n\nfunction fmtMoney(n){return fmt(n)+\" تومان\";}\nfunction humanDate(v){if(!v)return \"ثبت نشده\";try{const date=new Date(String(v).length===10?v+\"T12:00:00Z\":v);const hasTime=String(v).includes(\"T\");return new Intl.DateTimeFormat(\"fa-IR-u-ca-persian\",{timeZone:\"Asia/Tehran\",year:\"numeric\",month:\"long\",day:\"numeric\",...(hasTime?{hour:\"2-digit\",minute:\"2-digit\"}:{})}).format(date);}catch{return String(v)}}\nfunction pct(n,d){return d>0?(Math.round(n*1000/d)/10).toLocaleString(\"fa-IR\")+\"٪\":\"—\";}\nfunction note(text){return '<p class=\"explain\">'+text+'</p>';}\nfunction metricCard(label,value,foot,extra=\"\"){return '<div class=\"card\"><div class=\"label\">'+esc(label)+'</div><div class=\"big\">'+esc(value)+'</div><div class=\"foot\">'+esc(foot)+'</div>'+extra+'</div>';}\nfunction topNav(slug,selected){return '<div class=\"site-topnav\">'+siteSections.map(([key,icon,name])=>'<a data-link=\"'+sitePath(slug,key)+'\" class=\"topnav-link '+(selected===key?'selected':'')+'\" href=\"'+sitePath(slug,key)+'\">'+icon+' '+esc(name)+'</a>').join('')+'</div>';}\nfunction tableHeader(headers,rows){return '<div class=\"tablebox\"><table class=\"data-table\"><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>';}\nfunction csvExport(name,headers,rows){\n const safe=s=>{let v=String(s??'');if(/^[=+\\-@\\t\\r]/.test(v))v=\"'\"+v;return '\"'+v.replace(/\"/g,'\"\"')+'\"';};\n const txt='\\ufeff'+[headers,...rows].map(r=>r.map(safe).join(',')).join('\\r\\n');\n const href=URL.createObjectURL(new Blob([txt],{type:\"text/csv;charset=utf-8\"})),a=document.createElement('a');a.href=href;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(href),2000);\n}\nfunction overviewView(d){\n const orders=d.totals.orders,revenue=d.totals.revenue_toman,aov=orders?Math.round(revenue/orders):0;\n const isSession=d.totals.sessions!==null&&d.totals.sessions!==undefined;\n let h='<div class=\"cards\">'+metricCard('سفارش پرداخت‌شده',fmt(orders),'بر اساس سفارش‌های ووکامرس')+metricCard('مبلغ کل سفارش‌ها',fmt(revenue),'تومان · شامل ارسال و مالیات احتمالی')+metricCard('میانگین مبلغ سفارش',fmt(aov),'تومان به‌ازای هر سفارش')+metricCard('جلسات GA4',d.ga4?.period?fmt(d.ga4.channels.reduce((v,r)=>v+r.sessions,0)):'—',d.ga4?.period?'بازه GA4: '+humanDate(d.ga4.period.period_start)+' تا '+humanDate(d.ga4.period.period_end):'GA4 هنوز دریافت نشده است')+'</div>';\n h+='<div class=\"twocol section\">'+bar('کدام کانال سفارش بیشتری داشته؟',d.channels.slice(0,8),'orders')+bar('خریداران از چه نوع صفحه‌ای وارد شدند؟',d.types.slice(0,8),'orders')+'</div>';\n const highest=d.channels[0];\n h+='<div class=\"panel section\"><h3>در یک نگاه</h3><div class=\"insights\"><div>● '+(highest?'بیشترین سفارش‌های منتسب به کانال «'+esc(highest.channel)+'» بوده است ('+pct(highest.orders,orders)+').':'برای این دوره داده کانال موجود نیست.')+'</div><div>● مشاهده تعداد سفارش به‌تنهایی برای قضاوت درباره بازده تبلیغات کافی نیست؛ جلسات و هزینه جذب لازم است.</div><div>● «مستقیم / نامشخص» می‌تواند شامل ورودی‌هایی با منبع ناشناخته باشد؛ این مقدار معادل تایپ آدرس نیست.</div></div></div>';\n h+='<div class=\"panel section\"><div class=\"section-head\"><h3>کانال‌های اصلی</h3><a class=\"text-link\" data-link=\"'+sitePath(d.site.slug,'channels')+'\" href=\"'+sitePath(d.site.slug,'channels')+'\">تحلیل همه کانال‌ها ←</a></div>'+tableHeader(['کانال','تعداد سفارش','سهم سفارش','مبلغ سفارش‌ها'],d.channels.slice(0,6).map(x=>'<tr><td>'+esc(x.channel)+'</td><td>'+fmt(x.orders)+'</td><td>'+pct(x.orders,orders)+'</td><td>'+fmt(x.revenue_toman)+'</td></tr>'))+'</div>';\n h+='<div class=\"panel section\"><div class=\"section-head\"><h3>صفحات ورودی برتر</h3><a class=\"text-link\" data-link=\"'+sitePath(d.site.slug,'landing')+'\" href=\"'+sitePath(d.site.slug,'landing')+'\">جست‌وجو و مشاهده همه ←</a></div>'+tableHeader(['صفحه','نوع','سفارش','مبلغ'],d.landings.slice(0,7).map(x=>'<tr><td class=\"path\"><span dir=\"ltr\">'+esc(x.page_path)+'</span></td><td>'+esc(x.page_type)+'</td><td>'+fmt(x.orders)+'</td><td>'+fmt(x.revenue_toman)+'</td></tr>'))+'</div>';\n return h;\n}\nfunction channelsView(d){\n let h='<div class=\"section cards\">'+metricCard('کانال‌های ثبت‌شده',fmt(d.channels.length),'بر اساس WooCommerce Attribution')+metricCard('کانال پرفروش از نظر سفارش',d.channels[0]?.channel||'—',d.channels[0]?fmt(d.channels[0].orders)+' سفارش':'داده‌ای نیست')+metricCard('بیشترین مبلغ سفارش',fmt(d.channels.reduce((n,c)=>Math.max(n,c.revenue_toman),0)),'تومان')+metricCard('تعداد نشست و هزینه جذب','—','تا اتصال GA4 و داده تبلیغات قابل محاسبه نیست')+'</div>';\n h+='<div class=\"panel section\"><div class=\"section-head\"><h3>مقایسه کانال‌ها</h3><div class=\"toolbar\"><button class=\"btn secondary btn-sm chMetric\" data-metric=\"orders\">تعداد سفارش</button><button class=\"btn secondary btn-sm chMetric\" data-metric=\"revenue_toman\">مبلغ فروش</button></div></div><div id=\"channel-chart\"></div></div>';\n h+='<div class=\"panel section\"><h3>جدول عملکرد کانال‌ها</h3><div class=\"toolbar\"><input class=\"searchbox\" id=\"channelQuery\" placeholder=\"جست‌وجوی نام کانال...\" aria-label=\"جست‌وجو در کانال‌ها\"><button id=\"channelCsv\" class=\"btn secondary btn-sm\">دریافت CSV</button></div><div id=\"channel-table\"></div></div>';\n h+=note('مبلغ، کل مبلغ سفارش است و لزوماً درآمد خالص محصول نیست. نرخ تبدیل هر کانال و ROAS فقط با داده معتبر نشست و هزینه تبلیغات قابل محاسبه است. «ارجاع pl.snapp.ir» و «اسنپ‌پی (UTM)» دو منبع متفاوت‌اند؛ درباره منشأ ارجاع باید بررسی بیشتری انجام شود.');\n return h;\n}\nfunction landingView(d){\n return '<div class=\"panel section\"><div class=\"section-head\"><div><h3>تحلیل صفحات ورودی خریداران</h3><p class=\"hint\">ورودی ثبت‌شده توسط ووکامرس؛ اثبات‌کننده آخرین صفحه اثرگذار بر خرید نیست.</p></div><button id=\"landingCsv\" class=\"btn secondary btn-sm\">CSV صفحات فیلترشده</button></div><div class=\"toolbar\"><input class=\"searchbox\" id=\"landingQuery\" placeholder=\"جست‌وجوی آدرس یا عنوان مسیر...\" aria-label=\"جست‌وجوی مسیر صفحه\"><select class=\"searchbox\" id=\"pageType\" aria-label=\"نوع صفحه\"><option value=\"all\">همه انواع صفحه</option>'+[...new Set(d.landings.map(x=>x.page_type))].map(x=>'<option value=\"'+esc(x)+'\">'+esc(x)+'</option>').join('')+'</select><select class=\"searchbox\" id=\"landingSort\" aria-label=\"مرتب‌سازی\"><option value=\"orders\">بیشترین سفارش</option><option value=\"revenue\">بیشترین مبلغ</option><option value=\"path\">نام مسیر</option></select></div><div id=\"landingTable\"></div><div class=\"pager\" id=\"landingPager\"></div></div><p class=\"notice section\">جدول فعلی حداکثر ۱۰۰ صفحه برتر را از گزارش تجمیعی نمایش می‌دهد و همه صفحات فروشگاه را پوشش نمی‌دهد. برای محاسبه تأثیر واقعی محتوا، مسیر رویدادها باید به شناسه سفارش متصل شود.</p>';\n}\nfunction journeyView(d){\n let cells=[[\"مشاهده صفحه محصول\",\"view_item\",\"به GA4 نیاز دارد\"],[\"افزودن به سبد خرید\",\"add_to_cart\",\"به GA4 نیاز دارد\"],[\"شروع تسویه‌حساب\",\"begin_checkout\",\"به GA4 نیاز دارد\"],[\"خرید موفق\",\"WooCommerce\",fmt(d.totals.orders)+\" سفارش تأییدشده\"]];\n return '<div class=\"panel section\"><h3>قیف خرید: شفافیت وضعیت داده‌ها</h3><p class=\"hint\">برای جلوگیری از ارائه نرخ تبدیل اشتباه، رویدادهایی که هنوز دریافت نکرده‌ایم به‌صورت خالی می‌مانند.</p><div class=\"funnel\">'+cells.map((x,i)=>'<div class=\"funnel-step\"><span class=\"step-no\">'+(i+1)+'</span><div><b>'+esc(x[0])+'</b><small>'+esc(x[1])+'</small></div><span class=\"step-status\">'+esc(x[2])+'</span></div>').join('')+'</div></div><div class=\"panel section\"><h3>برای نمایش مسیر خرید هر سفارش چه لازم است؟</h3><p class=\"hint\">ارسال معتبر رویدادهای GA4، ذخیره شناسه سفارش در purchase، صادرات به BigQuery و اتصال شناسه‌های مجاز برای بازسازی توالی تعاملات. ضبط‌های Clarity فقط برای جلسات قابل‌دسترس به بررسی کیفی کمک می‌کنند.</p></div>';\n}\nfunction qualityView(d){\n const auto=d.period?.source==='woocommerce_auto';\n const success=d.integration?.status==='ok';\n const entries=[[\"منبع درآمد و سفارش\",auto?\"ووکامرس متصل\":\"گزارش تاریخی ووکامرس\",auto&&success?\"دریافت خودکار\":\"غیرلحظه‌ای\"],[\"بازه گزارش\",d.period?d.period.period_start+\" تا \"+d.period.period_end:\"—\",\"دوره ذخیره‌شده\"],[\"آخرین همگام‌سازی موفق\",d.integration?.last_success_at||\"هنوز انجام نشده\",success?\"موفق\":\"تأیید نشده\"],[\"وضعیت اتصال ووکامرس\",d.integration?.status||\"تعریف نشده\",d.integration?.error||\"—\"],[\"جلسات GA4\",\"دریافت نشده\",\"نرخ تبدیل قابل اتکا نیست\"],[\"هزینه تبلیغات\",\"دریافت نشده\",\"ROAS قابل محاسبه نیست\"],[\"داده روزانه و مقایسه دوره‌ها\",\"هنوز ذخیره نمی‌شود\",\"نمودار روند و رشد/افت نداریم\"],[\"جزئیات مسیر هر سفارش\",\"هنوز یکپارچه نشده\",\"رویداد و سفارش باید مرتبط شوند\"]];\n return '<div class=\"panel section\"><h3>شناسنامه و کیفیت داده‌های این سایت</h3>'+tableHeader(['موضوع','وضعیت','توضیح'],entries.map(x=>'<tr><td>'+esc(x[0])+'</td><td>'+esc(x[1])+'</td><td>'+esc(x[2])+'</td></tr>'))+'<p class=\"hint\">برای تصمیم‌های مدیریتی، تاریخ آخرین دریافت را با تاریخ پایان بازه مقایسه کنید. به‌روزرسانی صفحه مرورگر با دریافت داده جدید از فروشگاه تفاوت دارد.</p></div><div class=\"panel section\"><h3>روش انتساب فعلی</h3><p class=\"hint\">کانال‌ها و صفحات ورودی از متادیتای سفارش‌های WooCommerce برداشت می‌شوند؛ این داده ممکن است شامل منبع ناشناخته باشد و معادل انتساب نشست GA4 یا مدل چندلمسی نیست.</p></div>';\n}\nfunction channelDetails(d,label){const c=d.channels.find(z=>z.channel===label);if(!c)return \"\";return '<div class=\"detail\"><div class=\"section-head\"><h3>جزئیات «'+esc(c.channel)+'»</h3><button id=\"closeDetail\" class=\"btn secondary btn-sm\">بستن</button></div><div class=\"detail-cards\"><div><small>سفارش</small><b>'+fmt(c.orders)+'</b></div><div><small>سهم سفارش‌ها</small><b>'+pct(c.orders,d.totals.orders)+'</b></div><div><small>مبلغ</small><b>'+fmt(c.revenue_toman)+'</b></div><div><small>میانگین سفارش</small><b>'+fmt(c.orders?Math.round(c.revenue_toman/c.orders):0)+'</b></div></div><p class=\"hint\">نمایش صفحات و محصولات مخصوص همین کانال نیازمند داده ردیفی مشترک سفارش و صفحه است؛ این گزارش فعلاً به شکل تجمیعی ذخیره شده است.</p></div>';}\nfunction renderChannelTables(d){\n let q=($('#channelQuery')?.value||\"\").trim().toLowerCase();\n const filtered=d.channels.filter(x=>x.channel.toLowerCase().includes(q)),metric=panelState.metric;\n $('#channel-chart').innerHTML=bar(metric==='orders'?'سفارش به تفکیک کانال':'مبلغ سفارش به تفکیک کانال',filtered,metric);\n $('#channel-table').innerHTML=tableHeader(['کانال','تعداد سفارش','سهم سفارش','مبلغ کل (تومان)','سهم مبلغ','میانگین سفارش (تومان)'],filtered.map(x=>'<tr class=\"click-row\" tabindex=\"0\" data-channel=\"'+esc(x.channel)+'\"><td>'+esc(x.channel)+' ↗</td><td>'+fmt(x.orders)+'</td><td>'+pct(x.orders,d.totals.orders)+'</td><td>'+fmt(x.revenue_toman)+'</td><td>'+pct(x.revenue_toman,d.totals.revenue_toman)+'</td><td>'+fmt(x.orders?Math.round(x.revenue_toman/x.orders):0)+'</td></tr>'))+'<div id=\"channelDetails\"></div>';\n const opened=$('#channelDetails');if(panelState.channel)opened.innerHTML=channelDetails(d,panelState.channel);\n document.querySelectorAll('.click-row').forEach(el=>{const open=()=>{panelState.channel=el.dataset.channel;opened.innerHTML=channelDetails(d,panelState.channel);$('#closeDetail').onclick=()=>{panelState.channel=null;opened.innerHTML=\"\"};};el.onclick=open;el.onkeydown=e=>{if(e.key==='Enter')open()};});\n if($('#closeDetail'))$('#closeDetail').onclick=()=>{panelState.channel=null;opened.innerHTML=\"\"};\n document.querySelectorAll('.chMetric').forEach(b=>b.classList.toggle('active',b.dataset.metric===metric));\n}\nfunction filteredLandings(d){\n const q=panelState.query.trim().toLocaleLowerCase();\n return d.landings.filter(x=>(panelState.pageType===\"all\"||x.page_type===panelState.pageType)&&(!q||x.page_path.toLocaleLowerCase().includes(q)||x.page_type.includes(q))).sort((a,b)=>panelState.sort===\"revenue\"?b.revenue_toman-a.revenue_toman:panelState.sort===\"path\"?a.page_path.localeCompare(b.page_path):b.orders-a.orders);\n}\nfunction renderLandingTable(d){\n const all=filteredLandings(d),count=15,total=Math.max(1,Math.ceil(all.length/count));panelState.page=Math.min(panelState.page,total-1);const subset=all.slice(panelState.page*count,(panelState.page+1)*count);\n const origin='https://'+d.site.domain;\n $('#landingTable').innerHTML='<div class=\"results-meta\">'+fmt(all.length)+' نتیجه از '+fmt(d.landings.length)+' صفحه بارگذاری‌شده</div>'+tableHeader(['صفحه ورودی','نوع','سفارش','مبلغ کل','مشاهده'],subset.map(x=>{\n   let p=x.page_path,url=origin+(p.startsWith('/')?encodeURI(p):'');\n   if(!p.startsWith('/'))url=\"\";\n   return '<tr><td class=\"path\" title=\"'+esc(p)+'\">'+esc(p)+'</td><td>'+esc(x.page_type)+'</td><td>'+fmt(x.orders)+'</td><td>'+fmt(x.revenue_toman)+'</td><td>'+(url?'<a class=\"text-link\" href=\"'+esc(url)+'\" target=\"_blank\" rel=\"noopener noreferrer\">بازکردن ↗</a>':'—')+'</td></tr>';\n }))+(all.length?\"\":'<div class=\"empty\">صفحه‌ای با این فیلتر پیدا نشد.</div>');\n $('#landingPager').innerHTML='<span>صفحه '+fmt(panelState.page+1)+' از '+fmt(total)+'</span><div class=\"toolbar\"><button class=\"btn secondary btn-sm\" id=\"pagePrev\" '+(panelState.page===0?'disabled':'')+'>قبلی</button><button class=\"btn secondary btn-sm\" id=\"pageNext\" '+(panelState.page>=total-1?'disabled':'')+'>بعدی</button></div>';\n $('#pagePrev').onclick=()=>{panelState.page--;renderLandingTable(d)};$('#pageNext').onclick=()=>{panelState.page++;renderLandingTable(d)};\n}\nfunction dash(d,tab=\"overview\"){\n const s=d.site,has=!!d.period;const isAuto=d.period?.source===\"woocommerce_auto\";const freshness=d.integration?.last_success_at&&Date.now()-Date.parse(d.integration.last_success_at)<14400000;const title=siteSections.find(x=>x[0]===tab)?.[2]||\"نمای کلی\";\n const periodText=has?d.period.period_start+\" تا \"+d.period.period_end:\"داده‌ای ثبت نشده\";\n const subtitle=\"سایت \"+s.name+\" · \"+(has?humanDate(d.period.period_start)+\" تا \"+humanDate(d.period.period_end):periodText);\n const periodOptions=(d.periods||[]).map(p=>'<option value=\"'+esc([p.period_start,p.period_end,p.source].join(\"|\"))+'\" '+(d.period&&d.period.period_start===p.period_start&&d.period.period_end===p.period_end&&d.period.source===p.source?'selected':'')+'>'+esc(humanDate(p.period_start)+\" تا \"+humanDate(p.period_end)+(p.source===\"woocommerce_auto\"?\" · خودکار\":\" · آرشیوی\"))+'</option>').join('');\n let html=pageTitle(title+\" | \"+s.name,subtitle)+topNav(s.slug,tab)+'<div class=\"toolbar section\"><label class=\"period-picker\">دوره گزارش <select id=\"periodSelector\" class=\"searchbox\" aria-label=\"انتخاب دوره گزارش\">'+periodOptions+'</select></label><span class=\"pill\">'+esc(s.domain)+'</span><span class=\"pill '+(isAuto&&d.integration?.status==='ok'&&freshness?'':'pill-warn')+'\">'+(isAuto&&freshness?'تازه · ووکامرس':isAuto?'آخرین گزارش خودکار ووکامرس':'گزارش تاریخی ووکامرس')+'</span><span class=\"subtle-note\">آخرین دریافت موفق: '+esc(humanDate(d.integration?.last_success_at))+'</span><button id=\"download\" class=\"btn secondary btn-sm\">↓ خروجی CSV</button></div>';\n if(!has&&!(tab===\"traffic\"&&d.ga4?.period))html+='<div class=\"panel section empty\"><h3>هنوز داده‌ای برای '+esc(s.name)+' ثبت نشده است</h3><p>اتصال منبع اطلاعات این سایت از مدیریت مرکزی انجام می‌شود.</p></div>';\n else {\n  if(tab===\"channels\")html+=channelsView(d);\n  else if(tab===\"landing\")html+=landingView(d);\n  else if(tab===\"journey\")html+=journeyView(d);\n  else if(tab===\"quality\")html+=qualityView(d);\n  else html+=overviewView(d);\n }\n if(has&&tab===\"overview\")html+='<details class=\"panel section glossary\"><summary>راهنمای شاخص‌ها و تعریف دقیق اعداد</summary><p><b>سفارش پرداخت‌شده:</b> سفارش دارای تاریخ پرداخت در ووکامرس؛ شامل وضعیت‌های تکمیل‌شده و در حال پردازش.</p><p><b>مبلغ سفارش:</b> مبلغ کل ثبت‌شده سفارش، شامل هزینه ارسال و مالیات احتمالی؛ نه سود یا درآمد خالص محصول.</p><p><b>کانال جذب:</b> منبع منتسب به سفارش توسط متادیتای ووکامرس، نه انتساب قطعی GA4.</p><p><b>صفحه ورودی:</b> نخستین صفحه ذخیره‌شده برای نشست در متادیتای سفارش؛ لزوماً صفحه عامل خرید نیست.</p><p><b>«—»:</b> داده در دسترس نیست، نه اینکه مقدار آن صفر باشد.</p></details>';\n if((has||d.ga4?.period)&&tab!==\"quality\")html+='<p class=\"notice section\">شفافیت گزارش: منبع سفارش و مبلغ «ووکامرس» است. برای نرخ تبدیل، هزینه جذب و مسیر خرید کامل هنوز داده معتبر GA4 و اتصال سفارش لازم است. عدد «—» به معنی صفر نیست.</p>';\n $('#app').innerHTML=layout(html,s.slug,tab);\n const periodSelect=$('#periodSelector');if(periodSelect)periodSelect.onchange=e=>{const [a,b,source]=e.target.value.split(\"|\");nav(sitePath(s.slug,tab)+\"?\"+new URLSearchParams({period_start:a,period_end:b,source}).toString());};\n const btn=$('#download');if(btn)btn.onclick=()=>{if(!has)return;if(tab===\"landing\")csvExport(s.slug+\"-landings.csv\",[\"صفحه\",\"نوع\",\"سفارش\",\"مبلغ تومان\"],filteredLandings(d).map(x=>[x.page_path,x.page_type,x.orders,x.revenue_toman]));else csvExport(s.slug+\"-channels.csv\",[\"کانال\",\"سفارش\",\"مبلغ تومان\"],d.channels.map(x=>[x.channel,x.orders,x.revenue_toman]));};\n if(!has)return;\n if(tab===\"channels\"){renderChannelTables(d);$('#channelQuery').oninput=()=>renderChannelTables(d);document.querySelectorAll('.chMetric').forEach(el=>el.onclick=()=>{panelState.metric=el.dataset.metric;renderChannelTables(d);});$('#channelCsv').onclick=()=>csvExport(s.slug+\"-channels.csv\",[\"کانال\",\"سفارش\",\"سهم سفارش\",\"مبلغ\",\"میانگین\"],d.channels.map(x=>[x.channel,x.orders,pct(x.orders,d.totals.orders),x.revenue_toman,x.orders?Math.round(x.revenue_toman/x.orders):0]));}\n if(tab===\"landing\"){panelState.query=\"\";panelState.pageType=\"all\";panelState.page=0;panelState.sort=\"orders\";renderLandingTable(d);$('#landingQuery').oninput=e=>{panelState.query=e.target.value;panelState.page=0;renderLandingTable(d)};$('#pageType').onchange=e=>{panelState.pageType=e.target.value;panelState.page=0;renderLandingTable(d)};$('#landingSort').onchange=e=>{panelState.sort=e.target.value;panelState.page=0;renderLandingTable(d)};$('#landingCsv').onclick=()=>csvExport(s.slug+\"-filtered-landing-pages.csv\",[\"آدرس\",\"نوع\",\"سفارش\",\"مبلغ\"],filteredLandings(d).map(x=>[x.page_path,x.page_type,x.orders,x.revenue_toman]));}\n}\nasync function loadSites(){if(state.me.role==='admin'){const [a,b]=await Promise.all([api('/api/admin/sites'),api('/api/admin/users')]);state.sites=a.sites;state.users=b.users;}else {state.sites=[];state.users=[];}}\nasync function init(){try{state.me=(await api('/api/me')).user;await loadSites();if(state.me.role!=='admin'&&state.me.site_slug&&!location.pathname.startsWith('/s/'))history.replaceState({},'','/s/'+state.me.site_slug);await render();}catch{state.me=null;login();}}\n\nasync function render(){\n if(!state.me){login();return;}\n let match=location.pathname.match(/^\\/s\\/([a-z0-9-]+)(?:\\/(overview|traffic|channels|landing|journey|quality))?\\/?$/);\n if(state.me.role!==\"admin\"&&!match){history.replaceState({},'',sitePath(state.me.site_slug));match=location.pathname.match(/^\\/s\\/([a-z0-9-]+)(?:\\/(overview|channels|landing|journey|quality))?\\/?$/);}\n if(match){\n  try{\n   const slug=match[1],tab=match[2]||\"overview\";\n   const q=new URLSearchParams(location.search);const periodQuery=(q.has('period_start')&&q.has('period_end')&&q.has('source'))?'?'+new URLSearchParams({period_start:q.get('period_start'),period_end:q.get('period_end'),source:q.get('source')}).toString():'';\n   const [d,periodResponse]=await Promise.all([api('/api/dashboard/'+encodeURIComponent(slug)+periodQuery),api('/api/dashboard/'+encodeURIComponent(slug)+'/periods')]);d.periods=periodResponse.periods||[];\n   state.dashboard=d;dash(d,tab);\n  }catch(err){$('#app').innerHTML=layout(pageTitle('امکان مشاهده نیست',err.message),null);}\n }else if(state.me.role===\"admin\")siteManager();\n document.querySelectorAll('a[data-link]').forEach(a=>a.onclick=e=>{e.preventDefault();nav(a.dataset.link)});\n const out=$('#logout');if(out)out.onclick=async e=>{e.preventDefault();await api('/api/logout',{method:'POST',body:'{}'});state.me=null;history.replaceState({},'','/login');login();};\n}\nwindow.onpopstate=()=>render();init();\n";
